import { createOpenFeatureLocalStorageProvider, createOpenFeatureOFREPWebProvider } from '@grafana/runtime';
import { ClientProviderStatus, MultiProvider, OpenFeature, ProviderEvents, type Client, type JsonValue } from '@openfeature/web-sdk';

import { TrackingHook } from './tracking';
import { getObjectKeys } from '../../shared/utils/utils';
import { logger } from '../logger/logger';

/**
 * All feature flags that we intend to use from the GoFF service are defined here.
 * See {@link https://github.com/grafana/deployment_tools/blob/master/ksonnet/environments/hosted-grafana/waves/feature-toggles/goff/drilldown/metrics/flag-definitions.libsonnet | Metrics Drilldown GoFF flag definitions} for the source of truth.
 */
const goffFeatureFlags = {
  kgAnnotationsInMetricsDrilldown: {
    valueType: 'boolean',
    values: [true, false] as const,
    defaultValue: false,
  },
  'drilldown.metrics.slo_tracked_metrics': {
    valueType: 'boolean',
    values: [true, false] as const,
    defaultValue: false,
  },
  'drilldown.metrics.default_open_sidebar': {
    valueType: 'string',
    values: [
      'treatment', // The sidebar opens by default
      'control', // The sidebar remains closed (default behavior)
      'excluded', // The user is excluded from experiment (sidebar remains closed)
    ],
    defaultValue: 'excluded',
    trackingKey: 'experiment_default_open_sidebar',
  },
  'drilldown.metrics.grafana_assistant_quick_search_tab_test': {
    valueType: 'string',
    values: [
      'treatment', // Always show assistant button (when available); allows keyboard navigation to activate assistant
      'control', // Default behavior (current)
      'excluded', // User excluded from experiment (default behavior)
    ],
    defaultValue: 'excluded',
    trackingKey: 'experiment_grafana_assistant_quick_search_tab_test',
  },
  'drilldown.metrics.sort_by_firing_alerts': {
    valueType: 'string',
    values: [
      'treatment', // Firing-alerts sorting + chip + badge enabled
      'control', // Default behavior (feature hidden)
      'excluded', // User excluded from experiment (feature hidden)
    ],
    defaultValue: 'excluded',
    trackingKey: 'experiment_sort_by_firing_alerts',
  },
} as const satisfies Record<string, FeatureFlag>;

/**
 * This discriminated union captures the different types of feature flags that can be evaluated.
 *
 * @param valueType - The type of the feature flag value.
 * @param values - The possible values for the feature flag.
 * @param defaultValue - The default value for the feature flag.
 * @param trackingKey - If provided, the feature flag value will be tracked using the given key.
 */
type FeatureFlag =
  | {
      valueType: 'boolean';
      values: readonly boolean[];
      defaultValue: boolean;
      trackingKey?: string;
    }
  | {
      valueType: 'object';
      values: readonly JsonValue[];
      defaultValue: JsonValue;
      trackingKey?: string;
    }
  | {
      valueType: 'number';
      values: readonly number[];
      defaultValue: number;
      trackingKey?: string;
    }
  | {
      valueType: 'string';
      values: readonly string[];
      defaultValue: string;
      trackingKey?: string;
    };

const featureFlagNames = getObjectKeys(goffFeatureFlags);
export type FeatureFlagName = (typeof featureFlagNames)[number];
export type FlagValue<T extends FeatureFlagName> = (typeof goffFeatureFlags)[T]['values'][number];
export type FlagTrackingKey = (typeof goffFeatureFlags)[keyof typeof goffFeatureFlags] extends infer Flag
  ? Flag extends { trackingKey: infer K }
    ? K
    : never
  : never;

export const featureFlagTrackingKeys = Object.fromEntries(
  featureFlagNames.reduce<Array<[FeatureFlagName, FlagTrackingKey]>>((acc, flagName) => {
    const flagDef = goffFeatureFlags[flagName];
    if ('trackingKey' in flagDef) {
      acc.push([flagName, flagDef.trackingKey as FlagTrackingKey]);
    }
    return acc;
  }, [])
);

/**
 * OpenFeature domain for the metrics-drilldown plugin.
 * This isolates our provider from Grafana core and other plugins.
 */
export const OPEN_FEATURE_DOMAIN = 'metrics-drilldown';

/**
 * Initializes the OpenFeature provider for the metrics-drilldown plugin.
 * This function should be called once during app initialization.
 *
 * @remarks
 * The provider is only initialized if it hasn't been set yet (checked by comparing to default provider).
 * This prevents re-initialization if the app component re-renders.
 */
export function initOpenFeatureProvider(): Promise<void> {
  if (OpenFeature.getProvider(OPEN_FEATURE_DOMAIN) === OpenFeature.getProvider()) {
    return OpenFeature.setProviderAndWait(
      OPEN_FEATURE_DOMAIN,
      new MultiProvider([
        { provider: createOpenFeatureLocalStorageProvider() },
        { provider: createOpenFeatureOFREPWebProvider() },
      ])
    ).catch((error) => {
      // OpenFeature initialization may fail in environments without the feature flag service.
      // This is expected and the app will continue to work with default flag values.
      logger.warn('OpenFeature provider initialization failed, using default flag values', error);
    });
  }

  return Promise.resolve();
}

/**
 * Helper to wait for a client to be ready.
 */
function waitForClientReady(client: Client): Promise<void> {
  if (client.providerStatus === ClientProviderStatus.READY) {
    return Promise.resolve();
  }
  return new Promise((resolve) => {
    client.addHandler(ProviderEvents.Ready, () => resolve());
  });
}

/**
 * Evaluates a feature flag from the GoFF service.
 *
 * @param flagName - The name of the feature flag to evaluate.
 * @returns The value of the feature flag.
 */
export async function evaluateFeatureFlag<T extends keyof typeof goffFeatureFlags>(flagName: T): Promise<FlagValue<T>> {
  try {
    const client = OpenFeature.getClient(OPEN_FEATURE_DOMAIN);
    await waitForClientReady(client);
    client.addHooks(new TrackingHook());
    const flagDef = goffFeatureFlags[flagName] as FeatureFlag;

    switch (flagDef.valueType) {
      case 'boolean':
        const booleanValue = client.getBooleanValue(flagName, flagDef.defaultValue);
        return booleanValue as FlagValue<T>;
      case 'number':
        const numberValue = client.getNumberValue(flagName, flagDef.defaultValue);
        // @ts-expect-error - this can be removed once we add a number-type flag to `goffFeatureFlags`
        return numberValue as FlagValue<T>;
      case 'object':
        const objectValue = client.getObjectValue(flagName, flagDef.defaultValue);
        return objectValue as FlagValue<T>;
      case 'string':
        const stringValue = client.getStringValue(flagName, flagDef.defaultValue);
        return stringValue as FlagValue<T>;
      default:
        throw new Error(`Invalid flag value type for flag ${flagName}`);
    }
  } catch (error) {
    // On any error, default to default value
    logger.error(new Error(`Error evaluating ${flagName} flag.`, { cause: error }));
    return goffFeatureFlags[flagName].defaultValue as FlagValue<T>;
  }
}

/**
 * Whether the "sort by firing alerts" experiment feature (firing-alerts sort option, "Has firing alerts" filter
 * chip, and metric alert badges) should be shown to the current user.
 *
 * The `drilldown.metrics.sort_by_firing_alerts` flag is an A/B test with `treatment`/`control`/`excluded`
 * cohorts; only the `treatment` cohort sees the feature. Evaluating the flag also records the cohort for
 * analytics enrichment (see {@link TrackingHook}).
 */
export async function isFiringAlertsSortingEnabled(): Promise<boolean> {
  return (await evaluateFeatureFlag('drilldown.metrics.sort_by_firing_alerts')) === 'treatment';
}

/** Whether SLO-tracked metric filtering and indicators are enabled for the current stack. */
export async function isSloTrackingEnabled(): Promise<boolean> {
  return evaluateFeatureFlag('drilldown.metrics.slo_tracked_metrics');
}

/**
 * Eagerly evaluates experiment flags at app initialization so their cohort is recorded (via {@link TrackingHook})
 * before analytics events fire. This matters for A/B experiments whose primary KPI is a general event emitted by
 * both arms — e.g. `metric_selected` for the sort-by-firing-alerts experiment: the flag must be evaluated for
 * control users too, otherwise `getTrackedFlagPayload` returns null and the KPI event carries no cohort.
 *
 * Evaluating the flag is enough — the OpenFeature TrackingHook stores the cohort as a side effect; the returned
 * value is intentionally ignored here.
 */
export function evaluateExperimentFlagsEarly(): void {
  // `evaluateFeatureFlag` waits for the provider to be ready and swallows its own errors, so a failed evaluation
  // just leaves the cohort unset rather than throwing during startup.
  void evaluateFeatureFlag('drilldown.metrics.sort_by_firing_alerts');
}
